parameters.jsCode:
const e = $json || {};
const err = e.error || {};
const workflow = e.workflow || {};
const execution = e.execution || {};
const node = err.node || {};

return [{
  json: {
    workflow_name: workflow.name || 'Unknown',
    workflow_id: workflow.id || null,
    execution_id: e.executionId || execution.id || null,
    execution_url: e.executionUrl || '',
    node_name: node.name || err.nodeId || 'Unknown node',
    error_name: err.name || 'Error',
    error_message: err.message || 'No message provided',
    error_stack: err.stack || '',
    run_mode: e.runMode || '',
    url: e.url || '',
    sent_at: new Date().toISOString()
  }
}];

parameters.message:
Workflow: {{ $json.workflow_name }}
Execution ID: {{ $json.execution_id }}
Failed node: {{ $json.node_name }}

Error: {{ $json.error_name }} — {{ $json.error_message }}

--- Stack trace ---
{{ $json.error_stack }}

Run mode: {{ $json.run_mode }}
URL: {{ $json.url }}
Time: {{ $json.sent_at }}
